right_code.class:
// Informative, readable toString with explicit documentation
public final class PhoneNumber {
    private final short areaCode, prefix, lineNum;

    public PhoneNumber(int areaCode, int prefix, int lineNum) {
        this.areaCode = (short) areaCode;
        this.prefix   = (short) prefix;
        this.lineNum  = (short) lineNum;
    }

    public short getAreaCode() { return areaCode; }
    public short getPrefix()   { return prefix; }
    public short getLineNum()  { return lineNum; }

    /**
     * Returns the string representation of this phone number.
     * The string consists of twelve characters whose format is "XXX-YYY-ZZZZ".
     */
    @Override
    public String toString() {
        return String.format("%03d-%03d-%04d", areaCode, prefix, lineNum);
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        PhoneNumber jenny = new PhoneNumber(707, 867, 5309);
        // Clear, actionable log message:
        System.out.println("Failed to connect to: " + jenny);
        // Prints: Failed to connect to: 707-867-5309
    }
}
